async function saveQR(){let b=$('#saveQR'),name=$('#qrName').value.trim(),data=readData(),custom=kind==='bio'?'bio':slugify(customIdValue||$('#customId').value||slugify(name)+'-'+generatedSuffix);if(!name)return toast('Add a name first');customIdValue=custom;$('#customId').value=custom;let recordId=custom;if(kind==='bio'&&!editing&&items.some(x=>x.id==='bio'||x.type==='bio'))return toast('Bio links page already exists. Edit it from the library.');draftId=recordId;if(items.some(x=>x.id===recordId&&x.id!==editing?.id))return toast('This short ID is already in use. Choose another.');if(editing)recordId=editing.id;if(kind==='bio')recordId='bio';
const normalizeUrl=u=>{u=String(u||'').trim();if(!u)return '';if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(u))u='https://'+u;return u};if(kind==='url')data.url=normalizeUrl(data.url);if(kind==='video')data.videoUrl=normalizeUrl(data.videoUrl);if(kind==='payments')data.payments=data.payments.map(p=>({...p,url:normalizeUrl(p.url)}));if(kind==='app')data.links=data.links.map(p=>({...p,url:normalizeUrl(p.url)}));if(kind==='smartmap')data.branches=data.branches.map(p=>({...p,url:normalizeUrl(p.url)}));if(kind==='bio'){data.socials=data.socials.map(p=>{let raw=String(p.url||'').trim();if(p.platform==='phone'&&raw&&!/^tel:/i.test(raw))raw='tel:'+raw.replace(/[^0-9+*#;,]/g,'');else if(p.platform==='email'&&raw&&!/^mailto:/i.test(raw))raw='mailto:'+raw;else raw=normalizeUrl(raw);return {...p,url:raw}});data.links=data.links.map(p=>({...p,url:normalizeUrl(p.url)}))}const valid=u=>/^https?:\/\//i.test(u||'');
if(kind==='url'&&!valid(data.url))return toast('Enter a valid http(s) URL');if(kind==='text'&&!data.text.trim())return toast('Enter text');if(kind==='phone'&&!data.phone.trim())return toast('Enter a phone number');if(kind==='bank'&&!data.account.trim())return toast('Enter an account number or IBAN');if(kind==='payments'&&(!data.payments.length||data.payments.some(p=>!p.name.trim()||!valid(p.url))))return toast('Add valid payment methods');if(kind==='app'&&(!data.links.length||!data.links.some(p=>valid(p.url))))return toast('Add at least one valid app store URL');if(kind==='smartmap'&&(!data.branches.length||data.branches.some(p=>!valid(p.url))))return toast('Add at least one valid branch map URL');if(kind==='video'&&!valid(data.videoUrl))return toast('Enter a valid video URL');if(kind==='bio'&&(!data.company.trim()||!data.links.some(p=>(p.label||'').trim()&&valid(p.url))))return toast('Add a company name and at least one complete bio link');if(!qr)return toast('QR generator is not ready');
let record={...(editing||{}),id:recordId,name,type:kind,data,style:currentStyle(),active:editing?.active!==false,updatedAt:Date.now(),createdAt:editing?.createdAt||Date.now()};
b.disabled=true;b.textContent='Saving…';if($('#floatingSaveQR')){$('#floatingSaveQR').disabled=true;$('#floatingSaveQR').textContent='Saving…'}try{let result=await api('links/'+record.id,{method:'PUT',body:JSON.stringify(record)}),saved=result.item||record;items=[saved,...items.filter(x=>x.id!==saved.id)];cache();editing=null;draftData={};draftName='';draftStyle=null;customIdValue='';customIdTouched=false;kind='url';draftId=saved.id;toast('QR and dynamic link saved to Cloudflare KV');go('codes')}catch(e){toast('Cloud save failed: '+e.message)}finally{if($('#saveQR')){b.disabled=false;b.innerHTML=(editing?'Save changes':'Create QR')+' '+icon('fa-arrow-right')}if($('#floatingSaveQR')){let f=$('#floatingSaveQR');f.disabled=false;f.innerHTML=(lang==='ar'?'حفظ':'Save')}}}
function qrDownloadBase(){const raw=$('#qrName')?.value||draftName||'qr';const safeName=slugify(raw).replace(/^-+|-+$/g,'')||'qr';return `${safeName}-qr-byQRCo`}
function downloadQr(ext){if(!qr)return toast('QR generator is not ready');const name=qrDownloadBase();if(ext==='svg'||ext==='png'){qr.download({name,extension:ext});return}const canvas=$('#qrStage canvas');if(!canvas)return toast('Canvas preview is not ready');const a=document.createElement('a');a.href=canvas.toDataURL('image/webp',.94);a.download=`${name}.webp`;document.body.appendChild(a);a.click();a.remove()}
