function mergeRecords(a,b){const m=new Map();[...(a||[]),...(b||[])].forEach(x=>{if(x?.id){let old=m.get(x.id);if(!old||(x.updatedAt||0)>=(old.updatedAt||0))m.set(x.id,x)}});return [...m.values()]}
